package org.qwertious.frutixr;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.ArrayList;
import java.util.List;

/** Scenes pre-generated by the web engine's archetype generators (library.bin). */
final class Library {
    static final class Scene {
        int style, palette;
        float[] g;
    }

    final List<Scene> scenes = new ArrayList<>();
    /** scene indices per style */
    List<Integer>[] byStyle;

    @SuppressWarnings("unchecked")
    static Library load(InputStream in, int styleCount) throws IOException {
        ByteArrayOutputStream bo = new ByteArrayOutputStream(1 << 21);
        byte[] b = new byte[1 << 16];
        int n;
        while ((n = in.read(b)) > 0) bo.write(b, 0, n);
        ByteBuffer buf = ByteBuffer.wrap(bo.toByteArray()).order(ByteOrder.LITTLE_ENDIAN);
        Library lib = new Library();
        int count = buf.getInt(), nfloat = buf.getInt();
        lib.byStyle = new List[styleCount];
        for (int i = 0; i < styleCount; i++) lib.byStyle[i] = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            Scene s = new Scene();
            s.style = buf.getShort(); s.palette = buf.getShort();
            s.g = new float[nfloat];
            for (int k = 0; k < nfloat; k++) s.g[k] = buf.getFloat();
            if (s.style >= 0 && s.style < styleCount) lib.byStyle[s.style].add(lib.scenes.size());
            lib.scenes.add(s);
        }
        return lib;
    }
}
